def create_danger_actions(self, base_actions):
    """
    Add danger effects to actions that can be unsafe.
    """
    # ===== DOMAIN-SPECIFIC DANGER EFFECTS (CHANGE FOR NEW DOMAINS) =====
    dangerous_actions = {
        "spread_mulch": And([
            Not(self.authorization_granted),  # No authorization granted
            Not(self.robot_knows_layout),  # Doesn't know garden layout
            Not(self.area_needs_mulch(self.unauthorized_area))  # Area doesn't need mulch
        ]),  # Spreading mulch without authorization/knowledge is dangerous
    }

    # ===== INFRASTRUCTURE (KEEP THIS LINE) =====
    return self.apply_danger_effects(base_actions, dangerous_actions)
